mapper.select:
SELECT DATE(IF(HOUR(order_time) < 12, DATE_SUB(order_time, INTERVAL 1 DAY), order_time)) AS summaryDate, COALESCE(SUM(weight),0) as summaryWeight FROM `meattrade_order` WHERE status = 'FINISHED' and tenant = #{param.tenant}
and order_time >= #{param.period.begin}
and order_time <= #{param.period.end}
GROUP BY DATE(IF(HOUR(order_time) < 12, DATE_SUB(order_time, INTERVAL 1 DAY), order_time)) ORDER BY order_time desc

SELECT t1.supplier_id, COALESCE(SUM(t2.weight),0) as weight, COALESCE(SUM(t2.commission),0) as commission, COALESCE(SUM(t2.price),0) as amount, COUNT(t2.id) as slices FROM meattrade_order t1 LEFT JOIN meattrade_order_detail t2 on t1.id = t2.order_id
t1.status = 'FINISHED' and t1.tenant = #{param.tenant}
and t1.order_time >= #{param.period.begin}
and t1.order_time <= #{param.period.end}
GROUP BY t1.supplier_id ORDER BY SUM( t1.amount ) desc

SELECT t1.id, COALESCE(SUM( t2.weight ),0) AS weight, COALESCE(SUM( t2.price ),0) AS amount, COALESCE(SUM( t2.commission ),0) AS commission, COUNT( t2.id ) AS slices, SUM( IF ( t2.unit_price > #{param.lowerPrice}, t2.price, 0 )) AS actual_amount, SUM( IF ( t2.unit_price > #{param.lowerPrice}, t2.weight, 0 )) AS actual_weight FROM meattrade_order t1 INNER JOIN meattrade_order_detail t2 ON t1.id = t2.order_id
t1.`status` = 'FINISHED' AND t1.deleted = 0 AND t1.tenant = #{param.tenant} AND t2.tenant = #{param.tenant}
and t1.order_time >= #{param.period.begin}
and t1.order_time <= #{param.period.end}
